      if (/fire|flame|ember|cinder/.test(k)) return 'flame';
      if (/claw|fang|talon/.test(k)) return 'claw';
      if (/fist|punch|palm|brawler/.test(k)) return 'punch';
      if (/archer|bow|harpoon/.test(k)) return 'arrow';
      if (/blade|sword|knight|spear|lancer|duelist/.test(k)) return 'blade';
      if (/mage|caster|mystic|wizard/.test(k) || k === 'wraith' || k === 'healer') return 'magic';
